import subprocess, sys, os
def run(data, env=None, args=("testfilter",), cwd=None, exe="/workspace/executable"):
    e = dict(os.environ); e.pop("RICHGO_FORCE_COLOR", None); e.pop("RICHGO_LOCAL", None)
    e["RICHGO_FORCE_COLOR"]="1"
    if env: e.update(env)
    if isinstance(data,str): data=data.encode()
    p = subprocess.run([exe]+list(args), input=data, capture_output=True, env=e, cwd=cwd)
    return p
def show(data, **kw):
    p = run(data, **kw)
    print("IN :", repr(data if isinstance(data,str) else data.decode('utf8','replace')))
    print("OUT:", repr(p.stdout.decode('utf8','replace')).replace('\\x1b','\\e'))
    if p.stderr: print("ERR:", repr(p.stderr.decode('utf8','replace')))
    if p.returncode: print("RC :", p.returncode)
    print()
PYEOF
